-	struct crypto_tfm *tfm = crypto_skcipher_tfm(atfm);
-	struct sec_alg_tfm_ctx *ctx = crypto_tfm_ctx(tfm);
-
-	ctx->cipher_alg = alg;
-	memcpy(ctx->key, key, keylen);
-	sec_alg_skcipher_init_template(ctx, &ctx->req_template,
-				       ctx->cipher_alg);
-}
