-{
-	void __iomem *addr = queue->regs +  SEC_Q_ARUSER_CFG_REG;
-	u32 regval;
-
-	regval = readl_relaxed(addr);
-	if (ar_pkg)
-		regval |= SEC_Q_ARUSER_CFG_PKG;
-	else
-		regval &= ~SEC_Q_ARUSER_CFG_PKG;
-	writel_relaxed(regval, addr);
-
-	return 0;
-}
