-
-	if (domain && (domain->type & __IOMMU_DOMAIN_PAGING)) {
-		for (i = 0; i < SEC_Q_NUM; i++) {
-			sec_streamid(info, i);
-			/* Same QoS for all queues */
-			writel_relaxed(0x3f,
-				       info->regs[SEC_SAA] +
-				       SEC_Q_WEIGHT_CFG_REG(i));
-		}
-	}
-
-	for (i = 0; i < info->num_saas; i++) {
-		sec_saa_getqm_en(info, i, 1);
