-	if (ret)
-		return ret;
-
-	ret = sec_queue_map_io(queue);
-	if (ret) {
-		dev_err(info->dev, "Queue map failed %d\n", ret);
-		sec_queue_free_ring_pages(queue);
-		return ret;
-	}
-
-	sec_queue_hw_init(queue);
-
-	return 0;
-}
-
-static void sec_queue_unconfig(struct sec_dev_info *info,
